import { Download, ReceiptText } from "lucide-react";
import Link from "next/link";
import { Badge, Card, EmptyState, PageHeader } from "@/components/ui";
import { requireVendorFinance } from "@/lib/auth";
import { getDb } from "@/lib/db";
import { formatCurrency, formatDateTime } from "@/lib/format";

const labels: Record<string, string> = { queued: "排隊中", issued: "已開立", allowance: "已開立折讓", voided: "已作廢" };
const tones: Record<string, "gray" | "green" | "orange" | "red"> = { queued: "orange", issued: "green", allowance: "orange", voided: "red" };

export default async function ElectronicInvoicesPage() {
  const { vendor } = await requireVendorFinance("/billing/electronic-invoices");
  const invoices = await getDb().electronicInvoice.findMany({
    where: { vendorId: vendor.id },
    include: { order: { select: { orderNumber: true } }, allowances: { select: { id: true } } },
    orderBy: { createdAt: "desc" },
  });
  return <>
    <PageHeader title="電子發票" description="台灣 B2C 銷售發票、載具／統編快照與退款折讓狀態。" />
    <div className="mb-6 flex justify-end">
      <Link href="/billing/electronic-invoices/export" prefetch={false} className="inline-flex h-10 items-center gap-2 rounded-md border border-border px-4 text-sm font-semibold text-slate-700 hover:bg-slate-50"><Download size={16} />匯出開立報表 CSV</Link>
    </div>
    {invoices.length === 0 ? <EmptyState title="尚無電子發票" description="訂單付款後會自動排程開立，暫時排隊不會影響付款成功狀態。" /> :
      <Card className="overflow-hidden p-0"><div className="border-b border-border px-5 py-4"><h2 className="flex items-center gap-2 text-lg font-semibold"><ReceiptText size={18} />發票列表</h2></div>
        <div className="overflow-x-auto"><table className="w-full min-w-[980px] text-sm"><thead className="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th className="px-5 py-3">發票號碼</th><th className="px-5 py-3">訂單</th><th className="px-5 py-3">買受人／載具</th><th className="px-5 py-3">含稅金額</th><th className="px-5 py-3">未稅</th><th className="px-5 py-3">營業稅</th><th className="px-5 py-3">狀態</th><th className="px-5 py-3">開立時間</th></tr></thead>
          <tbody className="divide-y divide-border">{invoices.map((invoice) => <tr key={invoice.id}><td className="px-5 py-4 font-mono">{invoice.invoiceNumber ?? "排隊中"}</td><td className="px-5 py-4 font-semibold">{invoice.order.orderNumber}</td><td className="px-5 py-4">{invoice.buyerDisplay}</td><td className="px-5 py-4">{formatCurrency(invoice.amountCents, invoice.currency)}</td><td className="px-5 py-4">{formatCurrency(invoice.pretaxAmountCents, invoice.currency)}</td><td className="px-5 py-4">{formatCurrency(invoice.taxAmountCents, invoice.currency)}</td><td className="px-5 py-4"><Badge tone={tones[invoice.status] ?? "gray"}>{labels[invoice.status] ?? invoice.status}{invoice.allowances.length ? `（${invoice.allowances.length} 筆）` : ""}</Badge></td><td className="px-5 py-4 text-slate-500">{invoice.issuedAt ? formatDateTime(invoice.issuedAt) : "尚未開立"}</td></tr>)}</tbody>
        </table></div></Card>}
  </>;
}

import { renderToStaticMarkup } from "react-dom/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({ requireFinance: vi.fn(), findMany: vi.fn() }));
vi.mock("@/lib/auth", () => ({ requireVendorFinance: mocks.requireFinance }));
vi.mock("@/lib/db", () => ({ getDb: () => ({ electronicInvoice: { findMany: mocks.findMany } }) }));
import ElectronicInvoicesPage from "./page";

beforeEach(() => {
  vi.clearAllMocks();
  mocks.requireFinance.mockResolvedValue({ vendor: { id: "vendor-current" } });
  mocks.findMany.mockResolvedValue([{
    id: "invoice-1", invoiceNumber: "AB12345678", invoiceType: "company", buyerDisplay: "測試公司（統編末四碼 5257）",
    amountCents: 10_500, pretaxAmountCents: 10_000, taxAmountCents: 500, currency: "TWD", status: "allowance",
    issuedAt: new Date("2026-09-08T00:00:00Z"), order: { orderNumber: "ORDER-1" }, allowances: [{ id: "allowance-1" }],
  }]);
});

describe("ElectronicInvoicesPage", () => {
  it("queries only the authenticated vendor and renders the legal snapshot fields", async () => {
    const html = renderToStaticMarkup(await ElectronicInvoicesPage());
    expect(mocks.findMany).toHaveBeenCalledWith(expect.objectContaining({ where: { vendorId: "vendor-current" } }));
    for (const text of ["AB12345678", "ORDER-1", "統編末四碼 5257", "已開立折讓", "營業稅", "匯出開立報表 CSV"]) expect(html).toContain(text);
  });
});

"use client";

import { type FormEvent, useState } from "react";
import {
  isValidCitizenDigitalCertificate,
  isValidDonationCode,
  isValidMobileBarcode,
  isValidTaiwanBusinessId,
} from "@/lib/taiwan-invoice-validator";

export type CheckoutInvoiceFieldsValue = {
  type: "personal" | "company" | "donation";
  carrier?: "member" | "mobile" | "citizen_certificate";
  carrierNumber?: string;
  businessId?: string;
  companyName?: string;
  donationCode?: string;
};

const inputClass = "mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-base text-slate-950 focus:border-blue-500";

export function invoiceFieldError(value: CheckoutInvoiceFieldsValue): string | null {
  if (value.type === "company") {
    if (!isValidTaiwanBusinessId(value.businessId ?? "")) return "請輸入有效的 8 碼統一編號。";
    return value.companyName?.trim() ? null : "請填寫發票抬頭。";
  }
  if (value.type === "donation") return isValidDonationCode(value.donationCode ?? "") ? null : "愛心捐贈碼須為 3 至 7 碼數字。";
  if (value.carrier === "mobile") return isValidMobileBarcode(value.carrierNumber ?? "") ? null : "手機條碼格式不正確。";
  if (value.carrier === "citizen_certificate") return isValidCitizenDigitalCertificate(value.carrierNumber ?? "") ? null : "自然人憑證載具格式不正確。";
  return null;
}

function invoiceValueFromForm(form: HTMLFormElement): CheckoutInvoiceFieldsValue {
  const data = new FormData(form);
  const text = (name: string) => String(data.get(name) ?? "").trim();
  const type = text("invoiceType") as CheckoutInvoiceFieldsValue["type"];
  if (type === "company") return { type, businessId: text("invoiceBusinessId"), companyName: text("invoiceCompanyName") };
  if (type === "donation") return { type, donationCode: text("invoiceDonationCode") };
  return { type: "personal", carrier: (text("invoiceCarrier") || "member") as NonNullable<CheckoutInvoiceFieldsValue["carrier"]>, carrierNumber: text("invoiceCarrierNumber") };
}

export function CheckoutInvoiceFields({ disabled = false }: { disabled?: boolean }) {
  const [type, setType] = useState<CheckoutInvoiceFieldsValue["type"]>("personal");
  const [carrier, setCarrier] = useState<NonNullable<CheckoutInvoiceFieldsValue["carrier"]>>("member");
  const [error, setError] = useState<string | null>(null);
  function validateCurrentForm(event: FormEvent<HTMLFieldSetElement>) {
    if (event.currentTarget.form) setError(invoiceFieldError(invoiceValueFromForm(event.currentTarget.form)));
  }

  return (
    <fieldset className="grid gap-4 rounded-xl border border-amber-200 bg-amber-50/60 p-4" disabled={disabled} onInput={validateCurrentForm}>
      <legend className="px-1 text-lg font-bold text-slate-950">電子發票</legend>
      <label className="text-sm font-semibold text-slate-800">發票類型
        <select name="invoiceType" value={type} onChange={(event) => setType(event.target.value as CheckoutInvoiceFieldsValue["type"])} className={inputClass}>
          <option value="personal">個人電子發票</option>
          <option value="company">公司三聯發票</option>
          <option value="donation">捐贈發票</option>
        </select>
      </label>

      {type === "personal" ? <>
        <label className="text-sm font-semibold text-slate-800">載具
          <select name="invoiceCarrier" value={carrier} onChange={(event) => setCarrier(event.target.value as typeof carrier)} className={inputClass}>
            <option value="member">會員載具（結帳 Email）</option>
            <option value="mobile">手機條碼</option>
            <option value="citizen_certificate">自然人憑證</option>
          </select>
        </label>
        {carrier !== "member" ? <label className="text-sm font-semibold text-slate-800">
          {carrier === "mobile" ? "手機條碼" : "自然人憑證載具號碼"}
          <input
            name="invoiceCarrierNumber"
            required
            maxLength={carrier === "mobile" ? 8 : 16}
            pattern={carrier === "mobile" ? "/[0-9A-Z.+\\-_]{7}" : "[A-Z]{2}[0-9]{14}"}
            aria-describedby="invoice-carrier-help"
            className={inputClass}
          />
          <span id="invoice-carrier-help" className="mt-1 block text-xs font-normal text-slate-600">
            {carrier === "mobile" ? "格式：/ 加 7 碼大寫英數或 . + - _" : "格式：2 碼大寫英文加 14 碼數字"}
          </span>
        </label> : null}
      </> : null}

      {type === "company" ? <div className="grid gap-4 sm:grid-cols-2">
        <label className="text-sm font-semibold text-slate-800">統一編號
          <input name="invoiceBusinessId" inputMode="numeric" required minLength={8} maxLength={8} pattern="[0-9]{8}" className={inputClass} />
        </label>
        <label className="text-sm font-semibold text-slate-800">發票抬頭
          <input name="invoiceCompanyName" required maxLength={120} className={inputClass} />
        </label>
      </div> : null}

      {type === "donation" ? <label className="text-sm font-semibold text-slate-800">愛心捐贈碼
        <input name="invoiceDonationCode" inputMode="numeric" required minLength={3} maxLength={7} pattern="[0-9]{3,7}" className={inputClass} />
      </label> : null}
      <p role="alert" aria-live="polite" className="min-h-5 text-sm font-semibold text-red-700">{error}</p>
    </fieldset>
  );
}

import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { CheckoutInvoiceFields, invoiceFieldError } from "@/components/checkout-invoice-fields";

describe("CheckoutInvoiceFields", () => {
  it("renders personal, company, donation and carrier choices", () => {
    const html = renderToStaticMarkup(<CheckoutInvoiceFields />);
    expect(html).toContain('name="invoiceType"');
    expect(html).toContain('value="personal"');
    expect(html).toContain('value="company"');
    expect(html).toContain('value="donation"');
    expect(html).toContain('value="mobile"');
    expect(html).toContain('value="citizen_certificate"');
    expect(html).toContain('role="alert"');
  });

  it("returns immediate errors for invalid switched-field values", () => {
    expect(invoiceFieldError({ type: "personal", carrier: "mobile", carrierNumber: "/abc1234" })).toBe("手機條碼格式不正確。");
    expect(invoiceFieldError({ type: "personal", carrier: "mobile", carrierNumber: "/ABC1234" })).toBeNull();
    expect(invoiceFieldError({ type: "company", businessId: "12345678", companyName: "公司" })).toContain("統一編號");
    expect(invoiceFieldError({ type: "company", businessId: "04595257", companyName: "" })).toContain("抬頭");
    expect(invoiceFieldError({ type: "donation", donationCode: "123" })).toBeNull();
  });
});
